#include <Cellerator/compiler/reflection/define_identity_and_generation_behavior_under_inline_ir_v1.hh>
#include <cassert>
using namespace cellerator::compiler::reflection::v1;
int main(){ir_handle_v1 h{1,2,3,4,handle_kind_v1::operation,availability_phase_v1::semantic,handle_lifetime_v1::compilation};inline_identity_result_v1 r;inline_identity_request_v1 q{inline_identity_action_v1::one_to_one,{h},1,true,false};assert(derive_inline_identities_v1(q,&r)==inline_identity_status_v1::valid&&r.outputs[0].identity_low==2&&r.outputs[0].object_generation==5);q.action=inline_identity_action_v1::split;q.output_count=2;assert(derive_inline_identities_v1(q,&r)==inline_identity_status_v1::valid&&r.outputs[0].identity_low!=h.identity_low);q.action=inline_identity_action_v1::forced_reuse;q.output_count=1;q.unsafe_acknowledged=false;assert(derive_inline_identities_v1(q,&r)==inline_identity_status_v1::unsafe_not_acknowledged);q.unsafe_acknowledged=true;assert(derive_inline_identities_v1(q,&r)==inline_identity_status_v1::valid&&r.unsafe_reuse&&r.cold_lineage.size()==1);}
